import re, glob, os, datetime

sev_re = re.compile(r'\[(ERROR|WARNING|INFO|DEBUG)\]')
counts = {}  # date_str -> {sev: n}
all_sevs = {}
for f in sorted(glob.glob('/app/logs/*.log')):
    date = f.split('/')[-1].split('_')[0]
    d = {s: 0 for s in ('ERROR','WARNING','INFO','DEBUG')}
    for line in open(f, encoding='utf-8', errors='replace'):
        m = sev_re.search(line)
        if not m: 
            print("NO SEV:", f, line); continue
        s = m.group(1)
        d[s] += 1
    counts[date] = d

for date, d in counts.items():
    all_sevs[date] = d

def get(date, sev):
    return counts.get(date, {}).get(sev, 0)

ref = datetime.date(2025, 8, 12)
from datetime import date, timedelta

def dstr(x): return x.isoformat()

periods = {}

periods['today'] = {ref}
periods['last_7_days'] = {ref - timedelta(days=i) for i in range(7)}
periods['last_30_days'] = {ref - timedelta(days=i) for i in range(30)}
periods['month_to_date'] = {date(2025,8,1) + timedelta(days=i) for i in range((ref - date(2025,8,1)).days + 1)}
periods['total'] = {date.fromisoformat(k) for k in counts}

for p, ds in periods.items():
    row = {}
    for sev in ('ERROR','WARNING','INFO'):
        n = 0
        for dd in sorted(ds):
            if p == 'total':
                n += get(dd.isoformat(), sev)
            elif p == 'today':
                n += get(dd.isoformat(), sev)
            elif p == 'last_7_days':
                if (ref - dd).days <= 6 and (ref - dd).days >= 0: n += get(dd.isoformat(), sev)
            elif p == 'last_30_days':
                if (ref - dd).days <= 29 and (ref - dd).days >= 0: n += get(dd.isoformat(), sev)
            elif p == 'month_to_date':
                if dd >= date(2025,8,1) and dd <= ref: n += get(dd.isoformat(), sev)
        row[sev] = n
    periods[p] = row

# simpler: recompute cleanly
def count_in(dates, sev):
    n = 0
    for dd in sorted(dates):
        n += get(dd.isoformat(), sev)
    return n

for p, ds in [('today', {ref}), ('last_7_days', {ref - timedelta(days=i) for i in range(7)}),
              ('last_30_days', {ref - timedelta(days=i) for i in range(30)}),
              ('month_to_date', {date(2025,8,1) + timedelta(days=i) for i in range((ref-date(2025,8,1)).days+1)})]:
    periods[p] = {sev: count_in(ds, sev) for sev in ('ERROR','WARNING','INFO')}

periods['total'] = {sev: sum(get(k, sev) for k in counts) for sev in ('ERROR','WARNING','INFO')}

out = ["period,severity,count"]
for p in ('today','last_7_days','last_30_days','month_to_date','total'):
    for sev in ('ERROR','WARNING','INFO'):
        out.append(f"{p},{sev},{periods[p][sev]}")

print("\n".join(out))

# debug detail
print("\nDate range of files:", min(counts), "to", max(counts))
for k in sorted(counts):
    print(k, counts[k])
